async function loadSession(sessionId, signal) {
  const [redisData, introspectData] = await Promise.all([
    redis.get(`session:${sessionId}`),
    fetch(`/oauth/introspect/${sessionId}`, { signal }).then(r => r.text())
  ]);
  return redisData ?? introspectData;
}

public async Task<string> LoadSessionAsync(
    string sessionId, CancellationToken cancellationToken)
{
    var redisTask = _redis.GetDatabase().StringGetAsync(sessionId);
    var introspectTask = _http.GetStringAsync(
        $"/oauth/introspect/{sessionId}", cancellationToken);

    await Task.WhenAll(redisTask, introspectTask);
    return redisTask.Result.ToString() ?? introspectTask.Result;
}

const controller = new AbortController();
const timeout = setTimeout(() => controller.abort(), 30_000);

try {
  const res = await fetch('/api/report', { signal: controller.signal });
  return await res.json();
} catch (err) {
  if (err.name === 'AbortError') return null;
  throw err;
} finally {
  clearTimeout(timeout);
}

